.bulk-app .record-calendar-grid button:disabled{opacity:.3}
.bulk-app .record-calendar button:focus-visible{outline:2px solid #173fae;outline-offset:1px}
.bulk-app .record-date-summary{display:flex;align-items:center;font-size:12px;font-weight:550;color:#52627b;margin:10px 2px}
.bulk-app .date-record-card{padding:12px;margin:10px 0;border-radius:16px}
.bulk-app .record-card-heading{position:relative;padding-bottom:6px}
.bulk-app .record-card-heading h3{font-size:14px;line-height:1.45;margin:0 0 4px;overflow-wrap:anywhere}
.bulk-app .record-card-heading p{margin:0;font-size:11px;line-height:1.5;color:#78859a}
.bulk-app .record-plan-badge{display:inline-block;margin-top:5px;padding:2px 7px;max-width:100%;border-radius:7px;background:#eef2fa;color:#536685;font-size:10px;overflow-wrap:anywhere}
.bulk-app .date-record-card .rec-item{gap:8px;min-height:48px;padding:6px 0;border-top:1px solid #edf0f5}
.bulk-app .date-record-card .record-card-value{display:flex;align-items:center;justify-content:space-between;gap:8px;flex:1;min-width:0;min-height:44px;padding:8px 9px;border:1px solid #e3eaf8;border-radius:10px;background:#f6f8fd;color:#263451;font-size:15px;font-weight:650;line-height:1.5}
.bulk-app .date-record-card .record-edit-trigger::after{content:none}
.bulk-app .date-record-card .record-edit-label{font-size:10px;font-weight:550;white-space:nowrap;color:#506db7;flex-shrink:0}
.bulk-app .date-record-card .btn-hist-del{width:44px;min-width:44px;min-height:44px;padding:10px;border-color:#e9edf3;background:#fff;color:#8791a2}
.bulk-app .date-record-card .record-edit-form{margin-top:6px}
.bulk-app #recordsView .records-management{margin-top:20px;padding:2px 12px;background:#f7f9fc}
.bulk-app #recordsView .records-management>summary{font-size:12px}

